#!/usr/bin/env bash
# Lance l'audit rgaa-ci (axe + checks maison + IA) sur chaque plateforme, sortie dans pf-<nom>/.
# Pré-requis : .env avec ANTHROPIC_API_KEY. Usage : scripts/audits-plateformes.sh [nom ...]
set -u
cd "$(dirname "$0")/.."
set -a; source .env; set +a
export NODE_USE_ENV_PROXY=1   # le fetch natif Node ignore http_proxy sinon

declare -A PAGES
PAGES[geoportail-urbanisme]="https://www.geoportail-urbanisme.gouv.fr/ https://www.geoportail-urbanisme.gouv.fr/info-general/ https://www.geoportail-urbanisme.gouv.fr/map/ https://www.geoportail-urbanisme.gouv.fr/search/ https://www.geoportail-urbanisme.gouv.fr/services/ https://www.geoportail-urbanisme.gouv.fr/statistics/france/ https://www.geoportail-urbanisme.gouv.fr/login https://www.geoportail-urbanisme.gouv.fr/faq/ https://www.geoportail-urbanisme.gouv.fr/manuals/ https://www.geoportail-urbanisme.gouv.fr/contact/ https://www.geoportail-urbanisme.gouv.fr/accessibilite/ https://www.geoportail-urbanisme.gouv.fr/plan-site/"
PAGES[adresse]="https://adresse.data.gouv.fr/ https://adresse.data.gouv.fr/decouvrir-la-BAN https://adresse.data.gouv.fr/carte-base-adresse-nationale https://adresse.data.gouv.fr/programme-bal https://adresse.data.gouv.fr/outils https://adresse.data.gouv.fr/outils/telechargements https://adresse.data.gouv.fr/outils/api-doc/adresse https://adresse.data.gouv.fr/communaute/communes-partenaires https://adresse.data.gouv.fr/blog https://adresse.data.gouv.fr/nous-contacter https://adresse.data.gouv.fr/stats https://adresse.data.gouv.fr/accessibilite"
PAGES[mondiagartif]="https://mondiagartif.beta.gouv.fr/ https://mondiagartif.beta.gouv.fr/accessibilite https://mondiagartif.beta.gouv.fr/mentions-legales https://mondiagartif.beta.gouv.fr/confidentialit%C3%A9 https://mondiagartif.beta.gouv.fr/contact https://mondiagartif.beta.gouv.fr/users/signin/ https://mondiagartif.beta.gouv.fr/users/signup/"
PAGES[cartesgouv]="https://cartes.gouv.fr/ https://cartes.gouv.fr/decouvrir/ https://cartes.gouv.fr/explorer-les-cartes https://cartes.gouv.fr/rechercher-une-donnee/search https://cartes.gouv.fr/publier-une-donnee https://cartes.gouv.fr/catalogue https://cartes.gouv.fr/documentation https://cartes.gouv.fr/actualites https://cartes.gouv.fr/a-propos https://cartes.gouv.fr/accessibilite https://cartes.gouv.fr/plan-du-site"
PAGES[planification]="https://planification.climat-energie.gouv.fr/ https://planification.climat-energie.gouv.fr/documentation/ https://planification.climat-energie.gouv.fr/dreal-ddt/ https://planification.climat-energie.gouv.fr/liens-outils/ https://planification.climat-energie.gouv.fr/newsletter/ https://planification.climat-energie.gouv.fr/note-versions/ https://planification.climat-energie.gouv.fr/nous-contacter/ https://planification.climat-energie.gouv.fr/se-connecter/ https://planification.climat-energie.gouv.fr/accessibilite/ https://planification.climat-energie.gouv.fr/mentions-legales/ https://planification.climat-energie.gouv.fr/plan/"
PAGES[observatoire-foret]="https://observatoire.foret.gouv.fr/ https://observatoire.foret.gouv.fr/carte https://observatoire.foret.gouv.fr/catalogue https://observatoire.foret.gouv.fr/mon-territoire https://observatoire.foret.gouv.fr/indicateurs-gestion-durable https://observatoire.foret.gouv.fr/themes/climat https://observatoire.foret.gouv.fr/actualites https://observatoire.foret.gouv.fr/glossaire https://observatoire.foret.gouv.fr/contact https://observatoire.foret.gouv.fr/accessibilite https://observatoire.foret.gouv.fr/plan-du-site"
PAGES[ign]="https://www.ign.fr/ https://www.ign.fr/institut/lign-cartographe-du-service-public https://www.ign.fr/institut/nos-activites https://www.ign.fr/institut/notre-recherche https://www.ign.fr/institut/kiosque https://www.ign.fr/institut/nos-domaines-dintervention/foret https://www.ign.fr/institut/ressources-pedagogiques https://www.ign.fr/espace-presse https://www.ign.fr/institut/informations-legales-et-administratives https://www.ign.fr/institut/kiosque/le-processus-de-fabrication-dune-carte"
PAGES[geodesie]="https://geodesie.ign.fr/ https://geodesie.ign.fr/quest-ce-que-la-geodesie https://geodesie.ign.fr/les-systemes-geodesiques https://geodesie.ign.fr/le-reseau-geodesique-francais-1993-rgf93 https://geodesie.ign.fr/calculs-geodesiques https://geodesie.ign.fr/grilles-de-conversion https://geodesie.ign.fr/le-nivellement https://geodesie.ign.fr/metropole-et-corse https://geodesie.ign.fr/fiches/index.php https://geodesie.ign.fr/textes-et-decrets"
PAGES[remonterletemps]="https://remonterletemps.ign.fr/ https://remonterletemps.ign.fr/comparer/basic https://remonterletemps.ign.fr/telecharger https://remonterletemps.ign.fr/faq https://remonterletemps.ign.fr/actualites https://remonterletemps.ign.fr/accessibilite https://remonterletemps.ign.fr/cgu"
PAGES[geodata-paris]="https://geodata-paris.fr/fr/ https://geodata-paris.fr/fr/qui-sommes-nous https://geodata-paris.fr/fr/formations/formation-initiale https://geodata-paris.fr/fr/formation-initiale/cycle-ingenieur https://geodata-paris.fr/fr/nos-masters https://geodata-paris.fr/fr/formations/formation-professionnelle https://geodata-paris.fr/fr/comment-candidater-geodata-paris https://geodata-paris.fr/fr/la-recherche-geodata-paris https://geodata-paris.fr/fr/actualites https://geodata-paris.fr/fr/contacts https://geodata-paris.fr/fr/declaration-daccessibilite-rgaa https://geodata-paris.fr/fr/plan-du-site"
PAGES[boutique]="https://boutique.ign.fr/ https://boutique.ign.fr/cartes/cartes-randonnee-france/top25-seriebleue.html https://boutique.ign.fr/cartes-de-tourisme-france-top100d29-finistere-9782758553236-1.html https://boutique.ign.fr/customer/account/login/ https://boutique.ign.fr/customer/account/create/ https://boutique.ign.fr/checkout/cart/ https://boutique.ign.fr/commander-une-carte https://boutique.ign.fr/aide https://boutique.ign.fr/accessibilite https://boutique.ign.fr/effectuer-un-retour"
PAGES[macarte]="https://macarte.ign.fr/ https://macarte.ign.fr/atlas/ https://macarte.ign.fr/aide/tuto https://macarte.ign.fr/edition/carte/ https://macarte.ign.fr/edition/narration https://macarte.ign.fr/edition/statistique https://macarte.ign.fr/edition/adresses https://macarte.ign.fr/minecraft/ https://macarte.ign.fr/cgu https://macarte.ign.fr/mentions-legales https://macarte.ign.fr/cookies-et-statistiques"

ORDRE=(geoportail-urbanisme adresse mondiagartif cartesgouv planification observatoire-foret ign geodesie remonterletemps geodata-paris boutique macarte)
[[ $# -gt 0 ]] && ORDRE=("$@")

for nom in "${ORDRE[@]}"; do
  args=()
  for u in ${PAGES[$nom]}; do args+=(--url "$u"); done
  echo "################ $nom (${#args[@]} pages → pf-$nom/)"
  node bin/rgaa-ci.js "${args[@]}" --output "pf-$nom" --fail-on any --ai --quiet
  echo "→ $nom terminé (code $?)"
done
